//! The `bindings/<crate>.agent.md` file: rendering (SPEC 15.4) and staleness (SPEC 15.3).

use super::effects::ProposedEffect;
use super::pipeline::{BoundCrate, BoundItem};
use std::path::Path;

/// The first line of the description under `# Binding:` (SPEC 23.2): the one line read back.
const GENERATED_PREFIX: &str = "generated by agentmark bind \u{2014} ";

/// The two header lines, parsed back. Only the first is machine-read.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Header {
    pub crate_name: String,
    pub version: String,
    pub date: String,
}

/// `generated by agentmark bind — printpdf 0.7.0 — 2026-10-13`, the first line of the description
/// under `# Binding:` (before the properties).
pub fn parse_header(text: &str) -> Option<Header> {
    let first = text
        .lines()
        .take_while(|l| !l.starts_with("- ") && !l.starts_with("##"))
        .find(|l| l.starts_with(GENERATED_PREFIX))?;
    let rest = first.strip_prefix(GENERATED_PREFIX)?;
    let mut parts = rest.split(" \u{2014} ");
    let name_version = parts.next()?;
    let date = parts.next()?.trim().to_string();
    let (crate_name, version) = name_version.rsplit_once(' ')?;
    Some(Header {
        crate_name: crate_name.trim().to_string(),
        version: version.trim().to_string(),
        date,
    })
}

/// State of a binding file relative to the crate version we want.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Freshness {
    Missing,
    /// Header version equals the wanted version.
    Fresh,
    /// Generated for another version: the API may have changed.
    Stale { bound_version: String },
    /// Exists but has no generated header (hand-written, or header deleted): not ours to touch
    /// without `force`.
    Unmanaged,
}

/// `crate_name` is checked against the header too: a file generated for another crate is stale.
pub fn freshness(path: &Path, crate_name: &str, want_version: &str) -> std::io::Result<Freshness> {
    let text = match std::fs::read_to_string(path) {
        Ok(t) => t,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Freshness::Missing),
        Err(e) => return Err(e),
    };
    Ok(match parse_header(&text) {
        None => Freshness::Unmanaged,
        Some(h) if h.crate_name != crate_name => Freshness::Stale {
            bound_version: format!("{} {}", h.crate_name, h.version),
        },
        Some(h) if h.version == want_version => Freshness::Fresh,
        Some(h) => Freshness::Stale {
            bound_version: h.version,
        },
    })
}

/// The value of the top-level `- effect:` line, if there is one.
pub fn read_effect(text: &str) -> Option<String> {
    text.lines()
        .take_while(|l| !l.starts_with("##"))
        .find_map(|l| l.strip_prefix("- effect:"))
        .map(|v| v.trim().to_string())
}

/// One doc line: a single line, no newlines.
fn doc_line(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Render the whole file. Every bound item gets a description line under its heading (its
/// summary, or a plain fallback); the effect is always `unverified`.
pub fn render_binding(
    b: &BoundCrate,
    code_lang: &str,
    proposed: ProposedEffect,
    date: &str,
) -> String {
    let mut o = String::new();
    o.push_str(&format!("# Binding: {}\n", b.crate_name));
    o.push_str(&format!(
        "{GENERATED_PREFIX}{} {} \u{2014} {date}\n",
        b.crate_name, b.version
    ));
    o.push_str(&format!(
        "edit freely; re-run `agentmark bind {} --force` to regenerate\n\n",
        b.crate_name
    ));
    o.push_str(&format!("- crate: {}\n", b.crate_name));
    o.push_str("- effect: unverified\n");
    o.push_str(&format!("- proposed-effect: {proposed}\n"));
    for it in &b.items {
        o.push('\n');
        o.push_str(&render_item(it, code_lang));
    }
    for (name, rust) in &b.handle_types {
        o.push_str(&format!("\n## Handle: {name}\n  ```{code_lang}\n"));
        for l in wrap_type(rust, 116) {
            o.push_str(&format!("  {l}\n"));
        }
        o.push_str("  ```\n");
    }
    if !b.not_bound.is_empty() {
        o.push_str("\n## Not bound\n");
        for (name, reason) in &b.not_bound {
            let r = doc_line(reason);
            if r.is_empty() {
                o.push_str(&format!("- {name}\n"));
            } else {
                o.push_str(&not_bound_entry(name, &r));
            }
        }
    }
    o
}

/// A Rust type on lines of at most `width` characters: broken after a `, ` (Rust does not mind).
fn wrap_type(t: &str, width: usize) -> Vec<String> {
    // pieces end after a `, `; a piece longer than a line is cut after `::` and `<` too
    let mut atoms: Vec<String> = Vec::new();
    for piece in t.split_inclusive(", ") {
        if piece.chars().count() + 4 <= width {
            atoms.push(piece.to_string());
            continue;
        }
        let mut cur = String::new();
        for part in piece.split_inclusive(['<', ':']) {
            if !cur.is_empty() && cur.chars().count() + part.chars().count() + 4 > width {
                atoms.push(std::mem::take(&mut cur));
            }
            cur.push_str(part);
        }
        atoms.push(cur);
    }
    let mut lines: Vec<String> = Vec::new();
    let mut cur = String::new();
    for piece in atoms {
        if !cur.is_empty() && cur.chars().count() + piece.chars().count() > width {
            lines.push(cur.trim_end().to_string());
            cur = "    ".to_string();
        }
        cur.push_str(&piece);
    }
    lines.push(cur);
    lines
}

/// SPEC 18.3: no line over 120 characters, and generated files obey it too (Q110). Nothing is
/// cut (SPEC 15.2: never silently drop): a long reason continues on `  > ` comment lines under
/// the entry, each at most 120 characters.
///
/// A single word longer than a line is split without losing or adding anything (Q202): the line
/// that ends inside the word ends in a `\` marker, and the parser joins the next line to it
/// WITHOUT a space. So that a real backslash at the end of a wrapped line is not mistaken for the
/// marker, the trailing backslashes of every line that is followed by another are doubled; the
/// parser halves them again (`syntax::parser::join_wrapped`). A backslash counts two columns here, and a split
/// line keeps one column free for the marker, so the 120 limit holds (and text without backslashes
/// wraps exactly as before).
pub fn not_bound_entry(name: &str, reason: &str) -> String {
    const MAX: usize = 120;
    let cost = |s: &str| s.chars().map(|c| if c == '\\' { 2 } else { 1 }).sum::<usize>();
    let limit = MAX;
    let mut lines = vec![format!("- {name}:")];
    let mut split_after = vec![false];
    let mut width = cost(&lines[0]);
    let mut fresh = true; // nothing but the prefix on the current line yet
    for word in reason.split_whitespace() {
        let mut word = word.to_string();
        loop {
            let cur = lines.last_mut().unwrap();
            let room = limit.saturating_sub(width + 1);
            if cost(&word) <= room {
                cur.push(' ');
                cur.push_str(&word);
                width += 1 + cost(&word);
                fresh = false;
                break;
            }
            if fresh {
                // a single word longer than a line: split it, losing nothing
                let mut take = String::new();
                let room = room.saturating_sub(1); // the marker
                for ch in word.chars() {
                    if !take.is_empty() && cost(&take) + cost(&ch.to_string()) > room {
                        break;
                    }
                    take.push(ch);
                }
                word = word.chars().skip(take.chars().count()).collect();
                cur.push(' ');
                cur.push_str(&take);
                fresh = false;
                if word.is_empty() {
                    width += 1 + cost(&take);
                    break;
                }
                *split_after.last_mut().unwrap() = true;
            }
            lines.push("  >".to_string());
            split_after.push(false);
            width = 3;
            fresh = true;
        }
    }
    let last = lines.len() - 1;
    for (i, line) in lines.iter_mut().enumerate().take(last) {
        let run = line.chars().rev().take_while(|c| *c == '\\').count();
        line.truncate(line.len() - run);
        line.push_str(&"\\".repeat(run * 2 + usize::from(split_after[i])));
    }
    let mut out = lines.join("\n");
    out.push('\n');
    out
}

/// One bound item: the heading, its description line, a blank line and the fenced body (no blank
/// lines around the whole).
pub fn render_item(it: &BoundItem, code_lang: &str) -> String {
    let mut o = String::new();
    let doc = if it.summary.trim().is_empty() {
        format!("Calls `{}`.", it.path)
    } else {
        doc_line(&it.summary)
    };
    // the pipeline only binds an item whose lines fit (Q416)
    let lines = it.sig.heading_lines(it.heading.as_deref().unwrap_or(&it.name)).unwrap_or_else(|| vec![format!("## {}", it.sig.heading(&it.name))]);
    let mut lines = lines.into_iter();
    if let Some(h) = lines.next() {
        o.push_str(&h);
        o.push('\n');
    }
    o.push_str(&one_line_doc(&doc));
    o.push('\n');
    for l in lines {
        o.push_str(&l);
        o.push('\n');
    }
    o.push_str(&format!("  ```{code_lang}\n"));
    for l in it.body.lines() {
        if l.is_empty() {
            o.push('\n');
        } else {
            o.push_str(&format!("  {l}\n"));
        }
    }
    o.push_str("  ```\n");
    o
}

/// Add items written on demand (SPEC 15.2) to an existing binding file: they leave `## Not bound`
/// and become bound items, and the file is `unverified` again, because code nobody read was added
/// (an approval covers only what was there when it was given). Everything else in the file,
/// hand edits included, stays as it is.
pub fn add_on_demand(text: &str, added: &[BoundItem], code_lang: &str, proposed: ProposedEffect) -> String {
    let mut lines: Vec<String> = text.lines().map(String::from).collect();
    // top: effect and proposed effect
    let top_end = lines.iter().position(|l| l.starts_with("## ")).unwrap_or(lines.len());
    let mut proposed = proposed;
    if let Some(l) = lines[..top_end].iter().find_map(|l| l.strip_prefix("- proposed-effect:")) {
        let old = match l.trim() {
            "network" => ProposedEffect::Network,
            "local" => ProposedEffect::Local,
            _ => ProposedEffect::Pure,
        };
        proposed = proposed.max(old);
    }
    // no proposal on file: the class a person approved (or the file's own claim) is the floor
    if !lines[..top_end].iter().any(|l| l.starts_with("- proposed-effect:")) {
        let floor = match lines[..top_end].iter().find_map(|l| l.strip_prefix("- effect:")).map(str::trim) {
            Some("network") => ProposedEffect::Network,
            Some("local") => ProposedEffect::Local,
            _ => ProposedEffect::Pure,
        };
        proposed = proposed.max(floor);
    }
    let prop_line = format!("- proposed-effect: {proposed}");
    match lines[..top_end].iter().position(|l| l.starts_with("- proposed-effect:")) {
        Some(i) => lines[i] = prop_line,
        None => {
            let at = lines[..top_end].iter().position(|l| l.starts_with("- effect:")).map_or(top_end, |i| i + 1);
            lines.insert(at, prop_line);
        }
    }
    let top_end = lines.iter().position(|l| l.starts_with("## ")).unwrap_or(lines.len());
    match lines[..top_end].iter().position(|l| l.starts_with("- effect:")) {
        Some(i) => lines[i] = "- effect: unverified".into(),
        None => {
            let at = lines[..top_end].iter().position(|l| l.starts_with("- crate:")).map_or(top_end, |i| i + 1);
            lines.insert(at, "- effect: unverified".into());
        }
    }
    // the items leave `## Not bound`
    if let Some(h) = lines.iter().position(|l| l.trim_end() == "## Not bound") {
        let end = lines[h + 1..].iter().position(|l| l.starts_with("## ")).map_or(lines.len(), |i| h + 1 + i);
        let mut kept: Vec<String> = Vec::new();
        let mut entries = 0;
        let mut dropping = false;
        for l in &lines[h + 1..end] {
            if let Some(rest) = l.strip_prefix("- ") {
                let name = rest.split(':').next().unwrap_or("").trim();
                dropping = added.iter().any(|a| a.name == name);
                if !dropping {
                    entries += 1;
                }
            } else if !l.starts_with("  >") {
                dropping = false;
            }
            if !dropping {
                kept.push(l.clone());
            }
        }
        let tail: Vec<String> = lines[end..].to_vec();
        lines.truncate(h);
        if entries > 0 {
            lines.push("## Not bound".into());
            lines.extend(kept);
        } else {
            while lines.last().is_some_and(|l| l.trim().is_empty()) {
                lines.pop();
            }
        }
        if !tail.is_empty() {
            lines.push(String::new());
        }
        lines.extend(tail);
    }
    // the new items go in front of `## Not bound`, else at the end
    let mut block: Vec<String> = Vec::new();
    for it in added {
        block.extend(render_item(it, code_lang).lines().map(String::from));
        block.push(String::new());
    }
    match lines.iter().position(|l| l.trim_end() == "## Not bound") {
        Some(h) => {
            lines.splice(h..h, block);
        }
        None => {
            while lines.last().is_some_and(|l| l.trim().is_empty()) {
                lines.pop();
            }
            lines.push(String::new());
            block.pop();
            lines.extend(block);
        }
    }
    let mut out = lines.join("\n");
    out.push('\n');
    out
}

/// One description line (PROMPT step 12): the summary, shortened at a word boundary with `…` when it
/// would pass 118 characters.
fn one_line_doc(doc: &str) -> String {
    let mut flat = doc.split_whitespace().collect::<Vec<_>>().join(" ");
    // a description is a plain paragraph: it must not read as a list item, heading, note or fence
    let looks_like_markup = flat.starts_with(['-', '*', '+', '#', '>', '`'])
        || flat.split_once(". ").is_some_and(|(n, _)| !n.is_empty() && n.chars().all(|c| c.is_ascii_digit()));
    if looks_like_markup {
        flat = format!("About it: {flat}");
    }
    if flat.chars().count() <= 118 {
        return format!("{flat}\n");
    }
    let mut out = String::new();
    for w in flat.split(' ') {
        let add = if out.is_empty() { w.chars().count() } else { out.chars().count() + 1 + w.chars().count() };
        if add > 115 {
            break;
        }
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(w);
    }
    format!("{}…\n", out.trim_end_matches([',', ';', ':', ' ']))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_long_type_breaks_at_commas_and_then_at_paths_and_angle_brackets() {
        let t = format!("a::B<'static, {}::C<{}>>", "very_long_module_name::".repeat(6), "x::y::".repeat(12));
        let lines = wrap_type(&t, 60);
        assert!(lines.len() > 2 && lines.iter().all(|l| l.chars().count() <= 60), "{lines:?}");
        let joined: String = lines.iter().map(|l| l.trim()).collect::<Vec<_>>().join("");
        assert_eq!(joined.replace(' ', ""), t.replace(' ', ""));
    }

    #[test]
    fn header_round_trip() {
        let h = parse_header(
            "# Binding: pdf\ngenerated by agentmark bind \u{2014} printpdf 0.7.0 \u{2014} 2026-10-13\nedit freely\n\n- crate: printpdf\n",
        )
        .unwrap();
        assert_eq!(h.crate_name, "printpdf");
        assert_eq!(h.version, "0.7.0");
        assert_eq!(h.date, "2026-10-13");
        assert!(parse_header("# Binding: pdf\n").is_none());
    }

    #[test]
    fn effect_line_is_read_from_the_top_only() {
        let t = "# Binding: x\n- crate: x\n- effect: pure\n\n## f()\n- effect: local\n";
        assert_eq!(read_effect(t).as_deref(), Some("pure"));
    }
}
